import assert from 'node:assert/strict';
import path from 'node:path';
import {pathToFileURL} from 'node:url';
import {createInterface} from 'node:readline';
import {ROOT, bind, readJson, readBound, publish, same, sha, formal, fileSha,
  decodeDigestTransportV001, type Json} from './run_candidate_discovery_digest_skill_e2e_v001.mts';
import {runCandidateSelectionV001} from '../../runner/src/skills/candidate-selection-v001.js';
import {buildSelectionRequestV001, validateSelectionV001, promoteSelectionV001}
  from './candidate_selection_validation_v001.mts';
import {loadThinPlanContextV0, projectThinPlanV0, assertThinPlanV0,
  IMPLEMENTATIONS as PREVIOUS_IMPLEMENTATIONS, WORK as PREVIOUS_WORK}
  from './run_thin_plan_candidate_selection_v0.mts';

export const WORK = 'evals/clip_composition/outputs/presentation/work-contrast-thin-plan-20260909-v001';
const THIS_FILE = 'evals/clip_composition/run_contrast_thin_plan_v0.mts';
const IMPLEMENTATIONS = [...PREVIOUS_IMPLEMENTATIONS, THIS_FILE];
const INTENT = 'ぺこらと一緒にホラーゲームをプレイしているような疑似体験を見せる。';
const AUTHORIZATION = {
  schemaVersion: 'contrast-thin-plan-received-instruction-v0',
  instruction: 'ZEV進行管理２ 指示-022', approvalQuote: 'kawafmm承認済み。',
  scope: {productionIntentOnly: true, existingSelectionUnchanged: true, sameCandidates: true,
    noHumanAnswersInFormalInput: true, knownHumanCalibrationNotIndependentBlind: true,
    existingRetentionAndOutputReuse: true, purposeConditionedRetentionRequiresGptDecision: true,
    humanQualitySeparate: true, paidApi: false, newMaterial: false},
};
const out = (name: string) => `${WORK}/${name}`;

/** 021の固定済み消費経路を変更せず、対照意図を同じ最小planで投影する実験入口。 */
export async function loadContrastContextV0(planPath = out('fixed-plan.json')) {
  const plan = await readJson(planPath);
  const source = await loadThinPlanContextV0(`${PREVIOUS_WORK}/fixed-plan.json`);
  assert(same(plan.sourceContextBinding, source.planBinding), 'CONTRAST_SOURCE_CHANGED');
  const thin = await readBound(plan.thinPlanBinding); assertThinPlanV0(thin);
  assert.equal(thin.productionIntent, INTENT, 'CONTRAST_INTENT_CHANGED');
  assert(same(await readBound(plan.authorization), AUTHORIZATION), 'CONTRAST_AUTHORIZATION_CHANGED');
  assert.equal(plan.planId, 'contrast-thin-plan-ymUsGrT6EaA-20260909-v001');
  assert.equal(plan.outputRoot, WORK);
  assert(same(plan.implementationBindings.map((b: Json) => b.path), IMPLEMENTATIONS), 'CONTRAST_IMPLEMENTATIONS_CHANGED');
  for (const b of plan.implementationBindings) {
    assert.equal(await fileSha(path.join(ROOT, b.path)), b.fileSha256, 'CONTRAST_IMPLEMENTATION_CHANGED');
  }
  const expected = projectThinPlanV0(source, thin, {sourceContextBinding: source.planBinding,
    thinPlanBinding: plan.thinPlanBinding, authorization: plan.authorization, planId: plan.planId,
    outputRoot: plan.outputRoot, implementationBindings: plan.implementationBindings});
  assert(same(plan, expected), 'CONTRAST_PROJECTION_CHANGED');
  const c = {...source, plan, planBinding: bind(planPath, plan), thinPlan: thin,
    authorization: AUTHORIZATION, sourceContextBinding: source.planBinding};
  const before = buildSelectionRequestV001(source).input, after = buildSelectionRequestV001(c).input;
  assert.deepEqual(Object.keys(after).filter(k => !same((before as Json)[k], (after as Json)[k])), ['productionRequest']);
  return c;
}
export async function prepareContrastV0() {
  const source = await loadThinPlanContextV0(`${PREVIOUS_WORK}/fixed-plan.json`);
  const thin = {schemaVersion: 'production-intent-plan-v0' as const, productionIntent: INTENT};
  const thinPlanBinding = await publish(out('thin-plan-v0.json'), thin);
  const authorization = await publish(out('received-instruction.json'), AUTHORIZATION);
  const implementationBindings = await Promise.all(IMPLEMENTATIONS.map(async p => ({path: p, fileSha256: await fileSha(path.join(ROOT, p))})));
  const plan = projectThinPlanV0(source, thin, {sourceContextBinding: source.planBinding,
    thinPlanBinding, authorization, planId: 'contrast-thin-plan-ymUsGrT6EaA-20260909-v001', outputRoot: WORK, implementationBindings});
  const planBinding = await publish(out('fixed-plan.json'), plan);
  const c = await loadContrastContextV0();
  await publish(out('input-isolation-verification.json'), {
    schemaVersion: 'contrast-plan-input-isolation-v0', status: 'passed', planBinding,
    previousPlanBinding: source.planBinding, thinPlanBinding,
    changedInputFields: ['productionRequest'], previousIntent: source.thinPlan.productionIntent,
    currentIntent: c.thinPlan.productionIntent, structureConditionsUnchanged: true,
    candidateSetAndTextUnchanged: true, skillCriteriaValidatorPromotionUnchanged: true,
    humanAnswerFileReadForInput: false, historicalOutputUsageInInput: false,
    experimentClass: 'known-human-calibration-not-independent-blind', humanQuality: 'not-evaluated',
  });
  return planBinding;
}
export async function executeContrastV0() {
  const c = await loadContrastContextV0(), request = buildSelectionRequestV001(c);
  await publish(out('selection-request.json'), request);
  let response: Json | undefined;
  const result = await runCandidateSelectionV001(request.input, async input => {
    assert(same(input, request.input));
    process.stdout.write(JSON.stringify({event: 'contrast-judgment-required', requestFileSha256: sha(formal(request)), input}) + '\n');
    const lines = createInterface({input: process.stdin, crlfDelay: Infinity, terminal: false});
    try {
      for await (const line of lines) {response = decodeDigestTransportV001(line); break;}
    } finally {lines.close();}
    assert(response, 'CONTRAST_JUDGMENT_INPUT_CLOSED');
    await publish(out('selection-response.json'), response);
    return response.answer;
  });
  await publish(out('selection-result.json'), result);
  const fresh = await loadContrastContextV0();
  assert(same(fresh.planBinding, c.planBinding));
  const promoted = promoteSelectionV001(validateSelectionV001(fresh, request, response!, result));
  await publish(out('selection-validation.json'), promoted.validation);
  await publish(out('candidate-adoption.json'), promoted.adoption);
  return promoted;
}
export async function verifyContrastSelectionV0() {
  const c = await loadContrastContextV0();
  const [request, response, result, validation, adoption] = await Promise.all([
    'selection-request.json', 'selection-response.json', 'selection-result.json', 'selection-validation.json', 'candidate-adoption.json',
  ].map(n => readJson(out(n))));
  const promoted = promoteSelectionV001(validateSelectionV001(c, request, response, result));
  assert(same(promoted.validation, validation) && same(promoted.adoption, adoption));
  return {c, request, response, result, ...promoted};
}
if (process.argv[1] && import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href) {
  if (process.argv[2] === 'prepare') process.stdout.write(JSON.stringify(await prepareContrastV0()) + '\n');
  else if (process.argv[2] === 'verify') {await verifyContrastSelectionV0(); process.stdout.write('verified\n');}
  else {const p = await executeContrastV0(); process.stdout.write(JSON.stringify({event: 'contrast-complete', adopted: p.adoption.adoptedCandidates.map((r: Json) => r.candidateId)}) + '\n');}
}

import assert from 'node:assert/strict';
import path from 'node:path';
import {pathToFileURL} from 'node:url';
import {access} from 'node:fs/promises';
import {ROOT, bind, readJson, readBound, publish, same, fileSha, type Json, type Binding}
  from './run_candidate_discovery_digest_skill_e2e_v001.mts';
import {WORK, verifyContrastSelectionV0} from './run_contrast_thin_plan_v0.mts';
import {WORK as PREVIOUS_WORK} from './run_thin_plan_candidate_selection_v0.mts';
import {validateSelectionV001} from './candidate_selection_validation_v001.mts';
import {promoteSelectionForExecutionV001} from './run_candidate_selection_e2e_v001.mts';
import {projectAdoptedMediaRangesV001} from './adopted_media_manufacturing_v001.mts';
import {verifyThinPlanOutputReuseV0} from './verify_thin_plan_output_reuse_v0.mts';

async function retainExact(p: string, value: Json) {
  try {await access(path.join(ROOT, p));}
  catch (e) {if ((e as NodeJS.ErrnoException).code === 'ENOENT') return publish(p, value); throw e;}
  assert(same(await readJson(p), value), 'SAVED_CONTRAST_EVIDENCE_CHANGED');
  return bind(p, value);
}

export async function verifyContrastOutputV0() {
  const {c, request, response, result} = await verifyContrastSelectionV0();
  // 現在の正式採否から先に区間を再構築する。旧動画から今回の採否やカットを作らない。
  const rebuilt = promoteSelectionForExecutionV001(c, validateSelectionV001(c, request, response, result));
  const adoptionBinding = await retainExact(`${WORK}/machine-adoption.json`, rebuilt.adoption);
  const editPlanBinding = await retainExact(`${WORK}/edit-plan.json`, rebuilt.editPlan);
  const adequacy = await readJson(`${WORK}/retention-adequacy.json`);
  assert(same(adequacy.selectionResponseBinding, bind(`${WORK}/selection-response.json`, response)));
  assert(same(adequacy.existingRetentionBinding, c.plan.reuseInternalRetention));
  assert.equal(adequacy.status, 'sufficient-for-current-expected-value');
  assert.equal(adequacy.newPurposeConditionedRetentionJudgment, false);
  assert(same(adequacy.candidates.map((r: Json) => r.candidateId), rebuilt.adoption.adoptedCandidates.map((r: Json) => r.candidateId)));
  const previousProof = await verifyThinPlanOutputReuseV0(`${PREVIOUS_WORK}/fixed-plan.json`);
  const previousReuse = await readBound(previousProof.formalReuseInputBinding);
  const selected = previousReuse.comparisonOutput;
  const generation = await readBound(selected.base.generationManifest);
  const timeline = await readBound(selected.base.timeline);
  const sourceRoot = path.posix.dirname(c.plan.sourceContextBinding.path);
  const previousPlan = await readJson(`${sourceRoot}/fixed-plan.json`);
  const originalRoot = path.posix.dirname(previousPlan.sourceContextBinding.path);
  const inspection = await readJson(`${originalRoot}/source-media-inspection.json`);
  assert(same(inspection.sourceVideoBinding, rebuilt.editPlan.sourceVideoBinding));
  const currentProjection = projectAdoptedMediaRangesV001(rebuilt.editPlan, inspection.media);
  assert(same(currentProjection.mappings, generation.segments), 'CURRENT_COMPOSITION_NEEDS_DIFFERENT_MEDIA');
  assert(same(currentProjection.mappings.map(({audioSamples, ...s}: Json) => s), timeline.segments));
  assert.equal(await fileSha(path.join(ROOT, selected.video.path)), selected.video.fileSha256);
  const captionArtifacts: Json = {};
  for (const [key, binding] of Object.entries(selected.artifacts)) captionArtifacts[key] = await readBound(binding as Binding);
  assert.equal(selected.technicalQc, 'passed');
  const reuse = {schemaVersion: 'contrast-plan-formal-output-reuse-input-v0',
    planBinding: c.planBinding, authorizationBinding: c.plan.authorization,
    machineAdoptionBinding: adoptionBinding, editPlanBinding,
    retentionAdequacyBinding: bind(`${WORK}/retention-adequacy.json`, adequacy),
    previousMediaReverificationBinding: bind(`${PREVIOUS_WORK}/output-reuse-verification-v002.json`, previousProof),
    currentMediaMappings: currentProjection.mappings, selectedOutput: selected,
    comparisonOutput: previousReuse.selectedOutput, unchangedCaptionArtifacts: selected.artifacts,
    mode: 'existing-bytes-reused-after-new-selection-and-formal-range-reconstruction',
    newRendererExecution: false, inheritedHumanQuality: false};
  const reuseBinding = await retainExact(`${WORK}/formal-output-reuse-input.json`, reuse);
  const proof = {schemaVersion: 'contrast-plan-output-reuse-verification-v0', status: 'passed',
    planBinding: c.planBinding, formalReuseInputBinding: reuseBinding,
    implementationBinding: {path: 'evals/clip_composition/verify_contrast_thin_plan_v0.mts',
      fileSha256: await fileSha(path.join(ROOT, 'evals/clip_composition/verify_contrast_thin_plan_v0.mts'))},
    selectedOutput: selected.video, comparisonOutput: previousReuse.selectedOutput.video,
    adopted: rebuilt.adoption.adoptedCandidates.map((r: Json) => r.candidateId),
    retainedSegments: rebuilt.editPlan.segments.length,
    selectedFrames: timeline.baseMedia.expectedFrameCount,
    comparisonFrames: previousProof.selectedFrames,
    checks: {newSelectionValidatedAndPromoted: true, existingRetentionReconstructed: true,
      currentRangesMatchExistingFramesAndAudio: true, previousCommonCoreAndCaptionRepairReverified: true,
      rendererAdmissionAndQcBound: true, videoBytesAndObservedMediaReverified: true},
    newRenderCount: 0, newInternalRetentionJudgment: false, humanQuality: 'not-evaluated'};
  await retainExact(`${WORK}/output-reuse-verification-v002.json`, proof);
  return proof;
}
if (process.argv[1] && import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href) {
  process.stdout.write(JSON.stringify(await verifyContrastOutputV0()) + '\n');
}

import assert from 'node:assert/strict';
import test from 'node:test';
import {WORK, verifyContrastSelectionV0} from './run_contrast_thin_plan_v0.mts';
import {WORK as PREVIOUS_WORK, projectThinPlanV0} from './run_thin_plan_candidate_selection_v0.mts';
import {buildSelectionRequestV001, validateSelectionV001} from './candidate_selection_validation_v001.mts';
import {promoteSelectionForExecutionV001} from './run_candidate_selection_e2e_v001.mts';
import {readJson, readBound, same, bind, type Json} from './run_candidate_discovery_digest_skill_e2e_v001.mts';
const actual = await verifyContrastSelectionV0();
const {c, request, response, result} = actual;
test('only production intent differs in the actual formal Skill input', async () => {
  const previous = await readJson(`${PREVIOUS_WORK}/selection-request.json`);
  assert.deepEqual(Object.keys(request.input).filter(k => !same(previous.input[k], request.input[k])), ['productionRequest']);
  assert.equal(request.input.productionRequest, c.thinPlan.productionIntent);
  assert.deepEqual(Object.keys(c.thinPlan), ['schemaVersion', 'productionIntent']);
});
test('human judgments and previous outputs added to context do not enter the Skill', () => {
  const changed: Json = structuredClone(c);
  changed.humanReview = {expectedAdoptedCandidates: ['candidate-0003']};
  changed.retention.humanReview = 'expectation';
  changed.previousOutput = {adopted: 'all', duration: 161};
  assert(same(buildSelectionRequestV001(changed), request));
});
test('021 response cannot authorize 022 adoption', async () => {
  assert.throws(() => validateSelectionV001(c, request,
    { ...response, requestFileSha256: 'old-response' }, result), /JUDGMENT_PROVENANCE_INVALID/);
  const previous = await readJson(`${PREVIOUS_WORK}/selection-response.json`);
  assert.throws(() => validateSelectionV001(c, request, previous, result), /JUDGMENT_PROVENANCE_INVALID/);
});
test('judgment wording cannot be rewritten after the bound response', () => {
  const changed = structuredClone(result); changed.answer.decisions[0].reason = 'human-aligned rewrite';
  assert.throws(() => validateSelectionV001(c, request, response, changed), /JUDGMENT_PROVENANCE_INVALID/);
});
test('unvalidated retention edits cannot be promoted', () => {
  const changed = structuredClone(c); changed.retention.segments[0].sourceEndMs++;
  assert.throws(() => promoteSelectionForExecutionV001(changed,
    validateSelectionV001(c, request, response, result)), /RETENTION_RECONSTRUCTION_INVALID/);
});
test('current adopted candidates alone deterministically reconstruct formal edit input', async () => {
  const rebuilt = promoteSelectionForExecutionV001(c, validateSelectionV001(c, request, response, result));
  assert(same(rebuilt.adoption, await readJson(`${WORK}/machine-adoption.json`)));
  assert(same(rebuilt.editPlan, await readJson(`${WORK}/edit-plan.json`)));
  const selected = new Set(actual.adoption.adoptedCandidates.map((r: Json) => r.candidateId));
  assert(rebuilt.editPlan.segments.every((s: Json) => selected.has(s.candidateId)));
  assert.equal(rebuilt.adoption.historicalHumanQualityInherited, false);
});
test('changing intention invalidates its existing binding', async () => {
  const oldPlan = await readBound(c.sourceContextBinding);
  const source = {plan: oldPlan, planBinding: c.sourceContextBinding};
  assert.throws(() => projectThinPlanV0(source, {...c.thinPlan, productionIntent: 'different'}, {
    sourceContextBinding: source.planBinding, thinPlanBinding: c.plan.thinPlanBinding,
    authorization: c.plan.authorization, planId: c.plan.planId, outputRoot: WORK,
    implementationBindings: c.plan.implementationBindings,
  }), /THIN_PLAN_BINDING_CHANGED/);
  assert(same(bind(c.planBinding.path, c.plan), c.planBinding));
});

/** 有効候補間の出力判断。時刻・正式採用・製造の権限を持たない。 */
export const CANDIDATE_SELECTION_SKILL_V001 = Object.freeze({
  id: 'candidate-selection', version: 'v001', owner: 'ZEVG',
  question: 'この候補群の中から、最終動画に残すべき候補はどれか',
});
export type CandidateSelectionInputV001 = {
  schemaVersion: 'candidate-selection-input-v001';
  productionRequest: string; structureConditions: string[]; criteria: string[];
  sourceId: string;
  candidates: Array<{candidateId: string; sourceId: string; title: string;
    utterances: Array<{utteranceId: string; text: string}>}>;
};
export type CandidateSelectionAnswerV001 = {status: 'abstained'; reason: string} | {
  status: 'complete';
  decisions: Array<{
    candidateId: string; sourceId: string; decision: 'adopt' | 'reject';
    basis: 'distinct-highlight' | 'necessary-context' | 'necessary-structure' | 'redundant' | 'weak';
    reason: string; evidenceUtteranceIds: string[];
    comparisons: Array<{candidateId: string; evidenceUtteranceIds: string[]}>;
  }>;
};
export type CandidateSelectionResultV001 = {
  schemaVersion: 'candidate-selection-result-v001';
  skillId: 'candidate-selection'; skillVersion: 'v001'; answer: unknown;
};
const object = (v: unknown): v is Record<string, any> => v !== null && typeof v === 'object'
  && !Array.isArray(v) && [Object.prototype, null].includes(Object.getPrototypeOf(v));
const keys = (v: unknown, names: string[]): v is Record<string, any> => object(v)
  && Object.keys(v).length === names.length && names.every(k => Object.hasOwn(v, k));
const text = (v: unknown): v is string => typeof v === 'string' && v.trim().length > 0;
const id = (v: unknown): v is string => text(v) && /^[A-Za-z0-9][A-Za-z0-9._-]*$/u.test(v);
const list = (v: unknown): v is any[] => Array.isArray(v)
  && Object.keys(v).length === v.length && Array.from({length: v.length}, (_, i) => Object.hasOwn(v, i)).every(Boolean);
const nonempty = (v: unknown): v is any[] => list(v) && v.length > 0;
const ids = (v: unknown): v is string[] => nonempty(v) && v.every(id) && new Set(v).size === v.length;
function fail(s: string): never {throw new TypeError(s);}

/** 閉じた語彙により過去採否、尺、score、製造先を判断入力へ追加できない。 */
export function assertCandidateSelectionInputV001(v: unknown): asserts v is CandidateSelectionInputV001 {
  if (!keys(v, ['schemaVersion', 'productionRequest', 'structureConditions', 'criteria', 'sourceId', 'candidates'])
    || v.schemaVersion !== 'candidate-selection-input-v001' || !text(v.productionRequest) || !id(v.sourceId)
    || !nonempty(v.structureConditions) || !v.structureConditions.every(text)
    || !nonempty(v.criteria) || !v.criteria.every(text) || !nonempty(v.candidates)) fail('SELECTION_INPUT_INVALID');
  const seen = new Set<string>();
  for (const c of v.candidates) {
    if (!keys(c, ['candidateId', 'sourceId', 'title', 'utterances']) || !id(c.candidateId)
      || c.sourceId !== v.sourceId || seen.has(c.candidateId) || !text(c.title) || !nonempty(c.utterances)) fail('SELECTION_INPUT_INVALID');
    seen.add(c.candidateId);
    const utterances = new Set<string>();
    for (const u of c.utterances) {
      if (!keys(u, ['utteranceId', 'text']) || !id(u.utteranceId) || !text(u.text)
        || utterances.has(u.utteranceId)) fail('SELECTION_INPUT_INVALID');
      utterances.add(u.utteranceId);
    }
  }
}
export function assertCandidateSelectionAnswerV001(v: unknown): asserts v is CandidateSelectionAnswerV001 {
  if (keys(v, ['status', 'reason']) && v.status === 'abstained' && text(v.reason)) return;
  if (!keys(v, ['status', 'decisions']) || v.status !== 'complete' || !nonempty(v.decisions)) fail('SELECTION_ANSWER_INVALID');
  for (const d of v.decisions) {
    if (!keys(d, ['candidateId', 'sourceId', 'decision', 'basis', 'reason', 'evidenceUtteranceIds', 'comparisons'])
      || !id(d.candidateId) || !id(d.sourceId) || !['adopt', 'reject'].includes(d.decision)
      || !(d.decision === 'adopt' ? ['distinct-highlight', 'necessary-context', 'necessary-structure'] : ['redundant', 'weak']).includes(d.basis)
      || !text(d.reason) || !ids(d.evidenceUtteranceIds) || !list(d.comparisons)) fail('SELECTION_ANSWER_INVALID');
    for (const c of d.comparisons) {
      if (!keys(c, ['candidateId', 'evidenceUtteranceIds']) || !id(c.candidateId)
        || !ids(c.evidenceUtteranceIds)) fail('SELECTION_ANSWER_INVALID');
    }
  }
}
export function assertCandidateSelectionResultV001(v: unknown): asserts v is CandidateSelectionResultV001 {
  if (!keys(v, ['schemaVersion', 'skillId', 'skillVersion', 'answer'])
    || v.schemaVersion !== 'candidate-selection-result-v001' || v.skillId !== CANDIDATE_SELECTION_SKILL_V001.id
    || v.skillVersion !== CANDIDATE_SELECTION_SKILL_V001.version) fail('SELECTION_RESULT_INVALID');
  assertCandidateSelectionAnswerV001(v.answer);
}
export async function runCandidateSelectionV001(input: CandidateSelectionInputV001,
  judge: (input: CandidateSelectionInputV001) => Promise<unknown>): Promise<CandidateSelectionResultV001> {
  assertCandidateSelectionInputV001(input);
  const answer = await judge(structuredClone(input));
  return {schemaVersion: 'candidate-selection-result-v001', skillId: 'candidate-selection',
    skillVersion: 'v001', answer: structuredClone(answer)};
}

import {
  assertCandidateSelectionInputV001, assertCandidateSelectionResultV001,
  type CandidateSelectionInputV001, type CandidateSelectionAnswerV001,
} from '../../runner/src/skills/candidate-selection-v001.js';
import {speechRange, speechUnitsByIds} from '../../runner/src/transcript-utils.js';
import {bind, same, keys, sha, formal, canonicalSha, type Json}
  from './run_candidate_discovery_digest_skill_e2e_v001.mts';

export const SELECTION_CRITERIA = Object.freeze([
  '各候補が制作要求へ加える意味、独自の見どころ、理解に必要な文脈を比較し、全候補に採用または不採用と理由を返す。',
  '意味的重複、同じ役割の候補の追加価値、見どころの弱さ、全体構成での必要性を本文の根拠で判断する。',
  '尺、文字数、元動画位置、候補ID、過去の人間採否、fixture固有の本文規則、事前に決めた採用件数を単独の基準にしない。',
  '件数目標はない。不要な候補を落とすためだけに落とさず、必要な候補は全件でも残す。成立しない候補群は全件不採用にできる。',
  '時刻や候補内部の編集は返さない。採用順は元素材順を維持し、回答は入力候補順に返す。',
  '根拠は自候補と比較相手の既存発話IDで示す。映像を見たと主張せず、判断不能ならabstainedを返す。',
]);
export const SELECTION_POLICY = Object.freeze({
  judgment: 'new-current-codex-semantic-candidate-comparison',
  order: 'source-order-without-reordering', adoptionCountTarget: null,
  authority: 'validation-then-deterministic-promotion-then-executor',
  internalRetention: 'revalidate-and-reuse-existing-meaning-result-and-cut-evidence',
  captionDisplay: 'existing-skill', manufacturing: 'existing-common-core-and-renderer',
  humanQuality: 'pending-review', apiCommunication: false,
});
const fail: (code: string) => never = code => {throw new Error(`CANDIDATE_SELECTION: ${code}`);};
const id = (s: unknown): s is string => typeof s === 'string' && /^[A-Za-z0-9][A-Za-z0-9._-]*$/u.test(s);
const list = (a: unknown): a is any[] => Array.isArray(a) && a.length > 0
  && Object.keys(a).length === a.length && Array.from({length: a.length}, (_, i) => Object.hasOwn(a, i)).every(Boolean);
const out = (c: Json, name: string) => `${c.plan.outputRoot}/${name}`;

/** 旧採否情報を持たない候補正本から、既存発話・STT境界だけで範囲を再構成する。 */
export function resolveSelectionCandidatesV001(c: Json): Json[] {
  const set = c.candidateSet;
  if (!keys(set, ['schemaVersion', 'sourceId', 'sourceVideoBinding', 'transcriptBinding', 'utteranceBinding', 'origins', 'candidates'])
    || set.schemaVersion !== 'candidate-selection-candidate-set-v001' || set.sourceId !== c.plan.request.sourceId
    || !same(set.sourceVideoBinding, c.plan.request.sourceVideo) || !same(set.transcriptBinding, c.plan.request.transcript)
    || !same(set.utteranceBinding, c.plan.request.utterances) || !list(set.candidates)) fail('CANDIDATE_SET_INVALID');
  const index = new Map<string, number>(c.utterances.utterances.map((u: Json, i: number) => [u.utteranceId, i]));
  const seen = new Set<string>();
  let previousStart = -1;
  return set.candidates.map((row: Json) => {
    if (!keys(row, ['candidateId', 'sourceId', 'title', 'contextStartUtteranceId', 'contextEndUtteranceId', 'evidenceUtteranceIds'])
      || !id(row.candidateId) || seen.has(row.candidateId) || row.sourceId !== set.sourceId
      || typeof row.title !== 'string' || !row.title.trim() || !list(row.evidenceUtteranceIds)) fail('CANDIDATE_ROW_INVALID');
    seen.add(row.candidateId);
    const start = index.get(row.contextStartUtteranceId), end = index.get(row.contextEndUtteranceId);
    if (start === undefined || end === undefined || start > end) fail('CANDIDATE_BOUNDS_INVALID');
    if (start < previousStart) fail('CANDIDATE_SOURCE_ORDER_INVALID');
    previousStart = start;
    const included = c.utterances.utterances.slice(start, end + 1);
    const includedUtteranceIds = included.map((u: Json) => u.utteranceId);
    checkEvidence(row.evidenceUtteranceIds, includedUtteranceIds);
    const sourceSegmentIds = included.flatMap((u: Json) => u.sourceSegmentIds);
    const units = speechUnitsByIds(c.transcript, sourceSegmentIds);
    if (!same(units.map(u => u.id), sourceSegmentIds)) fail('CANDIDATE_TRANSCRIPT_MEMBERSHIP_INVALID');
    const sourceInterval = speechRange(c.transcript, sourceSegmentIds);
    if (sourceInterval.sourceStartMs !== included[0].sourceStartMs || sourceInterval.sourceEndMs !== included.at(-1).sourceEndMs
      || sourceInterval.sourceStartMs >= sourceInterval.sourceEndMs) fail('CANDIDATE_OFFICIAL_RANGE_INVALID');
    return {...structuredClone(row), includedUtteranceIds, sourceSegmentIds, sourceInterval};
  });
}
function checkEvidence(evidence: string[], allowed: string[]) {
  let previous = -1;
  if (!list(evidence)) fail('EMPTY_EVIDENCE');
  for (const u of evidence) {
    const n = allowed.indexOf(u);
    if (n < 0) fail('EVIDENCE_OUTSIDE_CANDIDATE');
    if (n <= previous) fail('EVIDENCE_DUPLICATE_OR_ORDER_INVALID');
    previous = n;
  }
}
export function buildSelectionInputV001(c: Json): CandidateSelectionInputV001 {
  const parents = resolveSelectionCandidatesV001(c);
  const utterances = new Map<string, Json>(c.utterances.utterances.map((u: Json) => [u.utteranceId, u]));
  const input: CandidateSelectionInputV001 = {
    schemaVersion: 'candidate-selection-input-v001', productionRequest: c.plan.request.purpose,
    structureConditions: structuredClone(c.plan.structureConditions), criteria: [...SELECTION_CRITERIA],
    sourceId: c.plan.request.sourceId,
    candidates: parents.map(p => ({candidateId: p.candidateId, sourceId: p.sourceId, title: p.title,
      utterances: p.includedUtteranceIds.map((utteranceId: string) => ({utteranceId, text: utterances.get(utteranceId)!.text}))})),
  };
  assertCandidateSelectionInputV001(input);
  return input;
}
export function buildSelectionRequestV001(c: Json) {
  const input = buildSelectionInputV001(c);
  return {schemaVersion: 'candidate-selection-request-v001', requestId: `${c.plan.planId}-selection`,
    planBinding: c.planBinding, candidateSetBinding: c.plan.request.candidateSet,
    input, inputCanonicalSha256: canonicalSha(input)};
}
const tokens = new WeakMap<object, Json>();
export function validateSelectionV001(context: Json, request: Json, response: Json, result: unknown) {
  const c = structuredClone(context);
  if (!same(c.planBinding, bind(c.planBinding.path, c.plan))
    || !same(c.plan.request.candidateSet, bind(c.plan.request.candidateSet.path, c.candidateSet))) fail('CONTEXT_BINDING_CHANGED');
  assertCandidateSelectionResultV001(result);
  if (!same(request, buildSelectionRequestV001(c))
    || !keys(response, ['schemaVersion', 'requestFileSha256', 'answer', 'judgmentNote'])
    || response.schemaVersion !== 'candidate-selection-response-v001'
    || response.requestFileSha256 !== sha(formal(request)) || !same(response.answer, result.answer)
    || typeof response.judgmentNote !== 'string' || !response.judgmentNote.trim()) fail('JUDGMENT_PROVENANCE_INVALID');
  const answer = result.answer as CandidateSelectionAnswerV001;
  if (answer.status !== 'complete') fail('SELECTION_ABSTAINED');
  const parents = resolveSelectionCandidatesV001(c);
  if (!same(answer.decisions.map(d => d.candidateId), parents.map(p => p.candidateId))) fail('DECISION_COVERAGE_MEMBERSHIP_OR_ORDER_INVALID');
  const byId = new Map<string, Json>(parents.map(p => [p.candidateId, p]));
  const adoptedIds = new Set(answer.decisions.filter(d => d.decision === 'adopt').map(d => d.candidateId));
  for (const d of answer.decisions) {
    const parent = byId.get(d.candidateId)!;
    if (d.sourceId !== parent.sourceId) fail('DECISION_SOURCE_MEMBERSHIP_INVALID');
    checkEvidence(d.evidenceUtteranceIds, parent.includedUtteranceIds);
    let previous = -1;
    if (parents.length > 1 && d.comparisons.length === 0) fail('CANDIDATE_COMPARISON_REQUIRED');
    for (const comparison of d.comparisons) {
      const other = byId.get(comparison.candidateId);
      const n = parents.findIndex(p => p.candidateId === comparison.candidateId);
      if (!other || other.candidateId === d.candidateId) fail('COMPARISON_MEMBERSHIP_INVALID');
      if (n <= previous) fail('COMPARISON_DUPLICATE_OR_ORDER_INVALID');
      previous = n;
      checkEvidence(comparison.evidenceUtteranceIds, other.includedUtteranceIds);
    }
    if (['redundant', 'necessary-context'].includes(d.basis)
      && !d.comparisons.some(p => adoptedIds.has(p.candidateId))) fail('ADOPTED_COMPARISON_REQUIRED');
  }
  const selected = parents.filter(p => adoptedIds.has(p.candidateId));
  for (let i = 1; i < selected.length; i++) {
    if (selected[i - 1].sourceInterval.sourceEndMs > selected[i].sourceInterval.sourceStartMs) fail('ADOPTED_CANDIDATES_OVERLAP');
  }
  const validation = {schemaVersion: 'candidate-selection-validation-v001', status: 'passed',
    planBinding: c.planBinding, candidateSetBinding: c.plan.request.candidateSet,
    requestBinding: bind(out(c, 'selection-request.json'), request),
    responseBinding: bind(out(c, 'selection-response.json'), response),
    resultBinding: bind(out(c, 'selection-result.json'), result as Json),
    checks: {idExistence: 'passed', sourceMembership: 'passed', fullCoverage: 'passed', duplicates: 'passed',
      sourceOrder: 'passed', evidenceMembershipAndOrder: 'passed', candidateBounds: 'passed',
      selectedNonOverlap: 'passed', provenance: 'passed', closedInputVocabulary: 'passed'},
    meaningQuality: 'human-review-pending'};
  const token = Object.freeze({status: 'validated-candidate-selection'});
  tokens.set(token, structuredClone({c, answer, parents, selected, validation}));
  return token;
}
/** 不透明な検査済みtokenだけを採用正本へ昇格。Skill結果やJSONコピーは受け付けない。 */
export function promoteSelectionV001(token: object) {
  const value = tokens.get(token);
  if (!value) fail('VALIDATED_SELECTION_REQUIRED');
  const {c, answer, parents, selected, validation} = structuredClone(value);
  const decisions = new Map<string, Json>(answer.decisions.map((d: Json) => [d.candidateId, d]));
  const adoption = {schemaVersion: 'candidate-selection-machine-adoption-v001', artifactId: `${c.plan.planId}-adoption`,
    authorityKind: 'fixed-plan-validated-candidate-selection-for-human-review',
    authorizationBinding: c.plan.authorization, planBinding: c.planBinding,
    candidateSetBinding: c.plan.request.candidateSet, resultBinding: validation.resultBinding,
    requestBinding: validation.requestBinding, responseBinding: validation.responseBinding,
    validatorResultBinding: bind(out(c, 'selection-validation.json'), validation),
    sourceVideoBinding: c.plan.request.sourceVideo, transcriptBinding: c.plan.request.transcript,
    utteranceBinding: c.plan.request.utterances,
    adoptedCandidates: selected.map((p: Json) => ({...p, judgment: decisions.get(p.candidateId)})),
    rejectedCandidates: parents.filter((p: Json) => decisions.get(p.candidateId)!.decision === 'reject')
      .map((p: Json) => ({...p, judgment: decisions.get(p.candidateId)})),
    order: 'source-order-without-reordering', individualCandidateHumanApproval: 'not-performed',
    historicalHumanQualityInherited: false, humanQuality: 'not-evaluated'};
  return {validation, adoption};
}

